import { Token, Lexer } from './lexer.js';
import { Operand, OperandParser } from './operands.js';

export type DirectiveType = 'ORG' | 'DB' | 'DW' | 'EQU' | 'PROC' | 'ENDP' | 'MODEL' | 'STACK' | 'DATA' | 'CODE' | 'ASSUME' | 'END' | 'TIMES';

export interface DupItem {
  count: number;
  values: (number | string)[];
}

export interface LabelItem {
  label: string;
}

export type DataItem = number | string | DupItem | LabelItem;

export interface ParsedInstruction {
  mnemonic: string;
  operands: Operand[];
  prefixBytes?: number[];
}

export interface ParsedDirective {
  type: DirectiveType;
  items: DataItem[];
  orgValue?: number;
  equValue?: number;
  timesTokens?: Token[];
  innerType?: 'DB' | 'DW';
}

export interface ParsedLine {
  lineNumber: number;
  label?: string;
  directive?: ParsedDirective;
  instruction?: ParsedInstruction;
}

export class Parser {
  static parseLine(lineText: string, lineNumber: number): ParsedLine {
    const tokens = Lexer.tokenizeLine(lineText, lineNumber);
    if (tokens.length === 0) {
      return { lineNumber };
    }

    let tokenIdx = 0;
    let label: string | undefined;

    // Check for label at start of line
    // Pattern 1: IDENTIFIER :
    if (tokens.length >= 2 && tokens[0].type === 'IDENTIFIER' && tokens[1].type === 'COLON') {
      label = tokens[0].text;
      tokenIdx = 2;
    }
    // Pattern 2: IDENTIFIER followed by directive (e.g. DIZI DB ...)
    else if (
      tokens.length >= 2 &&
      tokens[0].type === 'IDENTIFIER' &&
      ['DB', 'DW', 'EQU', 'PROC', 'ENDP'].includes(tokens[1].text.toUpperCase())
    ) {
      label = tokens[0].text;
      tokenIdx = 1;
    }

    if (tokenIdx >= tokens.length) {
      return { lineNumber, label };
    }

    const keyword = tokens[tokenIdx].text.toUpperCase();
    tokenIdx++;

    // Check for ORG directive
    if (keyword === 'ORG') {
      if (tokenIdx >= tokens.length) {
        throw new Error(`ORG directive missing address at line ${lineNumber}`);
      }
      const numTok = tokens[tokenIdx];
      if (numTok.type !== 'NUMBER' || numTok.value === undefined) {
        throw new Error(`Invalid address for ORG at line ${lineNumber}`);
      }
      return {
        lineNumber,
        label,
        directive: {
          type: 'ORG',
          items: [],
          orgValue: numTok.value
        }
      };
    }

    // Check for EQU directive
    if (keyword === 'EQU') {
      if (!label) {
        throw new Error(`EQU direktifi bir etiket adı gerektirir, satır: ${lineNumber}`);
      }
      const remaining = tokens.slice(tokenIdx);
      if (remaining.length === 0) {
        throw new Error(`EQU değeri eksik, satır: ${lineNumber}`);
      }
      const numTok = remaining[0];
      if (numTok.type !== 'NUMBER' || numTok.value === undefined) {
        throw new Error(`EQU sabit bir sayı değeri bekler, satır: ${lineNumber}`);
      }
      return {
        lineNumber,
        label,
        directive: {
          type: 'EQU',
          items: [numTok.value],
          equValue: numTok.value
        }
      };
    }

    // Check for PROC directive
    if (keyword === 'PROC') {
      return {
        lineNumber,
        label,
        directive: {
          type: 'PROC',
          items: []
        }
      };
    }

    // Check for ENDP directive
    if (keyword === 'ENDP') {
      return {
        lineNumber,
        directive: {
          type: 'ENDP',
          items: []
        }
      };
    }

    // Support common standard 8086 structural/segment directives (.MODEL, .STACK, .DATA, .CODE, ASSUME, END)
    if (['.MODEL', '.STACK', '.DATA', '.CODE', 'ASSUME', 'END'].includes(keyword)) {
      const dirType = (keyword.startsWith('.') ? keyword.slice(1) : keyword) as DirectiveType;
      return {
        lineNumber,
        label,
        directive: {
          type: dirType,
          items: []
        }
      };
    }

    // Check for DB or DW directives
    if (keyword === 'DB' || keyword === 'DW') {
      const items = this.parseDataItems(tokens.slice(tokenIdx), lineNumber);
      return {
        lineNumber,
        label,
        directive: {
          type: keyword as DirectiveType,
          items
        }
      };
    }

    // Check for TIMES directive (e.g. TIMES 510-($-$$) DB 0 or TIMES 64 DB 0)
    if (keyword === 'TIMES') {
      const remaining = tokens.slice(tokenIdx);
      const dbIdx = remaining.findIndex(t => ['DB', 'DW'].includes(t.text.toUpperCase()));
      if (dbIdx === -1) {
        throw new Error(`TIMES sonrasında DB veya DW direktifi bekleniyor, satır: ${lineNumber}`);
      }
      const timesTokens = remaining.slice(0, dbIdx);
      const innerKeyword = remaining[dbIdx].text.toUpperCase() as 'DB' | 'DW';
      const items = this.parseDataItems(remaining.slice(dbIdx + 1), lineNumber);
      return {
        lineNumber,
        label,
        directive: {
          type: 'TIMES',
          items,
          timesTokens,
          innerType: innerKeyword
        }
      };
    }

    // Check for instruction prefix (REP, REPE, REPZ, REPNE, REPNZ)
    let prefixBytes: number[] | undefined;
    let mnemonic = keyword;

    if (['REP', 'REPE', 'REPZ', 'REPNE', 'REPNZ'].includes(keyword)) {
      prefixBytes = (keyword === 'REPNE' || keyword === 'REPNZ') ? [0xF2] : [0xF3];
      if (tokenIdx >= tokens.length) {
        throw new Error(`Prefix '${keyword}' sonrasında komut bekleniyor, satır: ${lineNumber}`);
      }
      mnemonic = tokens[tokenIdx].text.toUpperCase();
      tokenIdx++;
    }

    const operandTokensList: Token[][] = [];
    let currentOpTokens: Token[] = [];

    for (let i = tokenIdx; i < tokens.length; i++) {
      const tok = tokens[i];
      if (tok.type === 'COMMA') {
        if (currentOpTokens.length > 0) {
          operandTokensList.push(currentOpTokens);
          currentOpTokens = [];
        } else {
          throw new Error(`Unexpected comma at line ${lineNumber}`);
        }
      } else {
        currentOpTokens.push(tok);
      }
    }
    if (currentOpTokens.length > 0) {
      operandTokensList.push(currentOpTokens);
    }

    const operands: Operand[] = [];
    for (const opTokens of operandTokensList) {
      operands.push(OperandParser.parse(opTokens));
    }

    return {
      lineNumber,
      label,
      instruction: {
        mnemonic,
        operands,
        prefixBytes
      }
    };
  }

  // Parses comma-separated data items for DB / DW, including DUP(...)
  private static parseDataItems(tokens: Token[], lineNumber: number): DataItem[] {
    const items: DataItem[] = [];
    let i = 0;

    while (i < tokens.length) {
      const tok = tokens[i];

      // String literal: DB 'Hello$'
      if (tok.type === 'STRING') {
        items.push(tok.text);
        i++;
      }
      // Number literal
      else if (tok.type === 'NUMBER' && tok.value !== undefined) {
        // Check if followed by DUP(...)
        if (i + 1 < tokens.length && tokens[i + 1].text.toUpperCase() === 'DUP') {
          const count = tok.value;
          i += 2; // skip number and DUP
          if (i >= tokens.length || tokens[i].type !== 'LPAREN') {
            throw new Error(`Expected '(' after DUP at line ${lineNumber}`);
          }
          i++; // skip '('

          // Read inside parentheses until ')'
          const dupValues: (number | string)[] = [];
          while (i < tokens.length && tokens[i].type !== 'RPAREN') {
            const innerTok = tokens[i];
            if (innerTok.type === 'NUMBER' && innerTok.value !== undefined) {
              dupValues.push(innerTok.value);
            } else if (innerTok.type === 'STRING') {
              dupValues.push(innerTok.text);
            } else if (innerTok.text === '?') {
              dupValues.push(0);
            } else if (innerTok.type !== 'COMMA') {
              throw new Error(`Invalid token in DUP: ${innerTok.text} at line ${lineNumber}`);
            }
            i++;
          }
          if (i >= tokens.length || tokens[i].type !== 'RPAREN') {
            throw new Error(`Missing ')' in DUP at line ${lineNumber}`);
          }
          i++; // skip ')'
          items.push({ count, values: dupValues });
        } else {
          items.push(tok.value);
          i++;
        }
      } else if (tok.type === 'IDENTIFIER') {
        items.push({ label: tok.text });
        i++;
      } else if (tok.text === '?') {
        items.push(0);
        i++;
      } else {
        throw new Error(`Unexpected token in data directive: ${tok.text} at line ${lineNumber}`);
      }

      // Check for comma separating items
      if (i < tokens.length) {
        if (tokens[i].type === 'COMMA') {
          i++;
        } else {
          throw new Error(`Expected ',' between data items at line ${lineNumber}`);
        }
      }
    }

    return items;
  }
}
